<script setup lang="ts">import { LockKeyhole } from 'lucide-vue-next'; definePageMeta({layout:false}); useSeoMeta({title:'Ingreso administrativo'}); const auth=useAuthStore(); const form=reactive({email:'',password:''}); const error=ref(''); const loading=ref(false); async function submit(){loading.value=true;error.value='';try{await auth.login(form.email,form.password);await navigateTo('/admin')}catch(e:any){error.value=e?.data?.detail||'Credenciales incorrectas'}finally{loading.value=false}}</script>
<template><main class="login-page"><section class="login-card card"><div class="login-brand"><LockKeyhole/><h1>FECOCLIMA IA</h1><p>Administración segura</p></div><form @submit.prevent="submit"><label><span class="label">Correo electrónico</span><input v-model.trim="form.email" class="input" type="email" autocomplete="username" required></label><label><span class="label">Contraseña</span><input v-model="form.password" class="input" type="password" autocomplete="current-password" required></label><p v-if="error" class="notice notice-danger">{{error}}</p><button class="btn btn-primary login-btn" :disabled="loading">{{loading?'Ingresando…':'Iniciar sesión'}}</button><div class="links"><NuxtLink to="/admin/recuperar-contrasena">¿Olvidó su contraseña?</NuxtLink><NuxtLink to="/fecoclima-ia">Volver al portal</NuxtLink></div></form></section></main></template>
<style scoped>.login-page{min-height:100vh;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at top,#4d9aca 0,#004481 65%,#003663 100%)}.login-card{width:min(100%,430px);padding:30px}.login-brand{text-align:center;margin-bottom:25px}.login-brand svg{width:52px;height:52px;color:var(--fc-primary)}h1{margin:8px 0 3px;color:var(--fc-primary)}.login-brand p{margin:0;color:var(--fc-text-muted)}form{display:flex;flex-direction:column;gap:16px}.login-btn{width:100%}.links{display:flex;justify-content:space-between;gap:10px;font-size:.84rem;color:var(--fc-primary)}</style>
